        description: "O bosque arbóreo Distancia. Todos os inimigos cujo quadrado o bosque começa ou atravessa durante o movimento sofrem 5d6 de concussão (salvaguarda básica de Fortitude CD 25). Em uma falha, o bosque carrega a criatura nos escudos, movendo-a na mesma distância e direção pelo resto do Distanciar.",
