        originalName: "Chorus of Croaks",
        actionType: "one",
        description: "A patrulha de batedores boggard solta um coro de coaxar aterrador. Qualquer criatura que não seja boggard a até 9 m fica Amedrontada 1 a menos que passe numa salvaguarda de Vontade CD 21; quem passa criticamente fica imune temporariamente por 1 minuto.",
