        originalName: "Wind-Up",
        actionType: "passive",
        description: "24 horas, Prestidigitação CD 27 (Desabilitar um Dispositivo), espera.\n\nPara o autômato de corda agir, outra criatura precisa dá-lo corda com uma chave única (1 minuto). Uma vez dado corda, permanece operacional pelo tempo listado; depois fica inconsciente do entorno e não age até receber corda de novo. Algumas habilidades gastam tempo operacional. Não pode gastar mais do que tem e desliga na hora se chegar a 0. Se não estiver claro quando recebeu corda, a maioria dos donos dá corda num horário fixo (em geral às 8h).\n\nUma criatura pode tentar Desabilitar um Dispositivo para destecer a corda (CD 27). Cada sucesso reduz 1 hora de tempo operacional (2 horas em sucesso crítico), mesmo em espera.\n\nEntrar em Espera (3 ações): o tempo operacional não cai, mas ele percebe o entorno (−2 de circunstância em Percepção). Não pode agir, salvo sair da espera como reação quando percebe uma criatura (rolando iniciativa se for o caso).",
