        originalName: "Overrun",
        actionType: "three",
        description: "O regimento veterano hobgoblin avança inexorável, esmagando inimigos no caminho. Distancia até o dobro do Deslocamento e pode se mover pelos espaços de criaturas Grande ou menores, causando 2d8+9 cortante (salvaguarda básica de Reflexos CD 25) a cada criatura cujo espaço entra. O regimento só pode tentar Atropelar a mesma criatura uma vez por uso. Quando o regimento é reduzido a 2 segmentos, o dano cai para 1d8+2 cortante.",
