        description: "Um tumulto proteano antecipa a presença mais provável de uma criatura por insight sobrenatural em probabilidades caóticas. Isso lhe concede a capacidade de sentir criaturas no alcance listado. Véu de Privacidade impede que uma criatura seja detectada pelo sentido de entropia automaticamente (sem teste de contrariar).",
