        description: "Os órgãos vitais de um proteano mudam de forma e posição o tempo todo. Imediatamente depois de sofrer dano de ácido, eletricidade ou sônico, ganha a quantidade listada de resistência àquele tipo de dano. Isso dura 1 hora ou até a próxima vez que o proteano sofrer dano de um dos outros tipos (caso em que a resistência muda para aquele tipo), o que ocorrer primeiro. O proteano é imune a efeitos de polimorfo a menos que seja um alvo disposto. Se estiver Cego ou Surdo, recupera-se automaticamente no fim do próximo turno, quando novos órgãos sensoriais crescem no lugar dos comprometidos.",
