        description: "Erguendo os escudos, a guarda viking Distancia até o dobro do Deslocamento enquanto protege o protegido. A guarda ganha +2 de circunstância na CA contra reações disparadas por este movimento. O protegido pode Distanciar a mesma distância como reação, movendo-se com a tropa para manter os bônus de Investida da Guarda durante este movimento.",
